import { forwardRef, useRef } from 'react';

const CustomInput = forwardRef(function CustomInput(props, ref) {
  return <input ref={ref} {...props} />;
});

function Form() {
  const inputRef = useRef(null);

  const focusInput = () => {
    inputRef.current.focus();
  };

  return (
    <>
      <CustomInput ref={inputRef} placeholder="Name" />
      <button onClick={focusInput}>Focus</button>
    </>
  );
}

import { forwardRef, useImperativeHandle, useRef } from 'react';

const VideoPlayer = forwardRef(function VideoPlayer(props, ref) {
  const internalRef = useRef();

  useImperativeHandle(ref, () => ({
    play() { internalRef.current.play(); },
    pause() { internalRef.current.pause(); },
    // Parent cannot call internal methods directly
  }));

  return <video ref={internalRef} src="/video.mp4" />;
});

function App() {
  const playerRef = useRef();

  return (
    <>
      <VideoPlayer ref={playerRef} />
      <button onClick={() => playerRef.current.play()}>Play</button>
      <button onClick={() => playerRef.current.pause()}>Pause</button>
    </>
  );
}
